    // overflow checks that the constant x is representable by its type.
    // For untyped constants, it checks that the value doesn't become
    // arbitrarily large.
    void rec::overflow(Checker* check, operand* x, token::Pos opPos)
    {
        assert(x->mode == constant_);

        if(rec::Kind(gocpp::recv(x->val)) == constant::Unknown)
        {
            // TODO(gri) We should report exactly what went wrong. At the
            // moment we don't have the (go/constant) API for that.
            // See also TODO in go/constant/value.go.
            rec::error(gocpp::recv(check), atPos(opPos), InvalidConstVal, "constant result is not representable"_s);
            return;
        }

        // Typed constants must be representable in
        // their type after each constant operation.
        // x.typ cannot be a type parameter (type
        // parameters cannot be constant types).
        if(isTyped(x->typ))
        {
            rec::representable(gocpp::recv(check), x, gocpp::getValue<Basic*>(types::under(x->typ)));
            return;
        }

        // Untyped integer values must not grow arbitrarily.
        // 512 is the constant precision
        auto prec = 512;
        if(rec::Kind(gocpp::recv(x->val)) == constant::Int && constant::BitLen(x->val) > prec)
        {
            auto op = opName(x->expr);
            if(op != ""_s)
            {
                op += " "_s;
            }
            rec::errorf(gocpp::recv(check), atPos(opPos), InvalidConstVal, "constant %soverflow"_s, op);
            x->val = constant::MakeUnknown();
        }
    }

