    // representable checks that a constant operand is representable in the given
    // basic type.
    void rec::representable(Checker* check, operand* x, Basic* typ)
    {
        auto [v, code] = rec::representation(gocpp::recv(check), x, typ);
        if(code != 0)
        {
            rec::invalidConversion(gocpp::recv(check), code, x, typ);
            x->mode = invalid;
            return;
        }
        assert(v != nullptr);
        x->val = v;
    }

    // representation returns the representation of the constant operand x as the
    // basic type typ.
    //
    // If no such representation is possible, it returns a non-zero error code.
    std::tuple<constant::Value, errors::Code> rec::representation(Checker* check, operand* x, Basic* typ)
    {
        assert(x->mode == constant_);
        auto v = x->val;
        if(! representableConst(x->val, check, typ, & v))
        {
            if(isNumeric(x->typ) && isNumeric(typ))
            {
                // numeric conversion : error msg
                // integer -> integer : overflows
                // integer -> float   : overflows (actually not possible)
                // float   -> integer : truncated
                // float   -> float   : overflows
                if(! isInteger(x->typ) && isInteger(typ))
                {
                    return {nullptr, TruncatedFloat};
                }
                else
                {
                    return {nullptr, NumericOverflow};
                }
            }
            return {nullptr, InvalidConstVal};
        }
        return {v, 0};
    }

    void rec::invalidConversion(Checker* check, errors::Code code, operand* x, golang::types::Type target)
    {
        auto msg = "cannot convert %s to type %s"_s;
        //Go switch emulation
        {
            auto condition = code;
            int conditionId = -1;
            if(condition == TruncatedFloat) { conditionId = 0; }
            else if(condition == NumericOverflow) { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    msg = "%s truncated to %s"_s;
                    break;
                case 1:
                    msg = "%s overflows %s"_s;
                    break;
            }
        }
        rec::errorf(gocpp::recv(check), x, code, msg, x, target);
    }

    // convertUntyped attempts to set the type of an untyped value to the target type.
    void rec::convertUntyped(Checker* check, operand* x, golang::types::Type target)
    {
        auto [newType, val, code] = rec::implicitTypeAndValue(gocpp::recv(check), x, target);
        if(code != 0)
        {
            auto t = target;
            if(! isTypeParam(target))
            {
                t = safeUnderlying(target);
            }
            rec::invalidConversion(gocpp::recv(check), code, x, t);
            x->mode = invalid;
            return;
        }
        if(val != nullptr)
        {
            x->val = val;
            rec::updateExprVal(gocpp::recv(check), x->expr, val);
        }
        if(newType != x->typ)
        {
            x->typ = newType;
            rec::updateExprType(gocpp::recv(check), x->expr, newType, false);
        }
    }

